command:
// Avance le jeton de N cases droit devant lui, le premier mur l'arrêtant, et
// joue l'animation de charge. Appelée par DAE depuis l'effet d'une aptitude :
//     macro.execute | "Charge forward" 5
// Les guillemets sont nécessaires : DAE découpe la valeur du changement en
// jetons, et un nom nu serait tronqué à son premier mot.
//
// DAE relance la macro au RETRAIT de l'effet, avec « off » en premier argument :
// sans cette garde, le jeton chargerait une seconde fois en perdant l'effet.
// Lancée à la main depuis la barre, la macro n'a pas d'argument et avance le
// jeton sélectionné de cinq cases.
if (args?.[0] === "off") {
  return;
}

const charger = token ?? canvas.tokens.controlled[0];
if (!charger) {
  ui.notifications.warn(game.i18n.localize("FQCARDENGINE.MacroErrorMsgNoChargingToken"));
  return;
}

const steps = Number(args?.[1]) || 5;
const gridSize = canvas.grid.size;

// Convention d'orientation de Foundry, celle que le moteur applique lui-même :
// rotation = atan2(dy, dx) - 90°, donc l'avant du jeton vaut (-sin, cos).
const radians = (charger.document.rotation * Math.PI) / 180;
const forward = {x: -Math.sin(radians), y: Math.cos(radians)};

// Un point de passage PAR CASE : Foundry coupe le trajet au premier point
// bloqué par un mur, le jeton s'arrête donc sur la dernière case atteignable.
// Une seule étape de cinq cases, elle, serait annulée d'un bloc.
const waypoints = Array.from({length: steps}, (_, step) => ({
  x: Math.round((charger.document.x + (forward.x * gridSize * (step + 1))) / gridSize) * gridSize,
  y: Math.round((charger.document.y + (forward.y * gridSize * (step + 1))) / gridSize) * gridSize,
  snapped: true
}));

await new Sequence()
  .effect()
    .file("jb2a.smoke.puff.side.grey")
    .atLocation({x: charger.center.x, y: charger.center.y})
    .scaleToObject(2)
  .play();

await charger.document.move(waypoints, {autoRotate: false});

new Sequence()
  .effect()
    .file("jb2a.impact.ground_crack.01.orange")
    .atLocation(charger)
    .scaleToObject(1.5)
  .play();
